-- Keep the exact generated bytes in the same private row as their history
-- metadata. The original contract may be purged without removing this copy.
ALTER TABLE yzy_contracts.generated_documents
  ADD COLUMN artifact bytea,
  ADD CONSTRAINT generated_documents_artifact_shape CHECK (
    artifact IS NULL OR (
      (format IN ('pdf', 'docx') OR
        (format = 'email' AND (email->>'attachment_format' IN ('pdf', 'docx')) IS TRUE))
      AND NOT imported_from_session
      AND octet_length(artifact) BETWEEN 1 AND 20971520
    )
  );
